/* @autogenerated */
package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.*;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.Response;
import net.civeira.phylax.common.exception.StepUpRequiredException;
import net.civeira.phylax.common.infrastructure.exceptionmapper.StepUpRequiredExceptionMapper;
import net.civeira.phylax.common.security.impl.ActorImpl;

@DisplayName("Actor second factor checks")
class ActorStepUpUnitTest {

  @Test
  @DisplayName("Should accept a token with mfa")
  void shouldAcceptMfa() {
    Actor actor = ActorImpl.builder().uid("u").authenticated(true).mfa(true).build();

    assertTrue(actor.hasMfa());
    assertDoesNotThrow(() -> actor.requireMfa());
  }

  @Test
  @DisplayName("Should ask for step up without mfa")
  void shouldAskStepUpWithoutMfa() {
    Actor actor = ActorImpl.builder().uid("u").authenticated(true).build();

    StepUpRequiredException ex = assertThrows(StepUpRequiredException.class, actor::requireMfa);
    assertTrue(ex.getMaxAge().isEmpty());
  }

  @Test
  @DisplayName("Should ask for step up with max age when the mfa login is too old")
  void shouldAskStepUpWhenOld() {
    Actor actor = ActorImpl.builder().uid("u").authenticated(true).mfa(true)
        .authenticatedAt(Instant.now().minus(Duration.ofMinutes(10))).build();

    assertDoesNotThrow(() -> actor.requireMfa(Duration.ofMinutes(15)));
    StepUpRequiredException ex =
        assertThrows(StepUpRequiredException.class, () -> actor.requireMfa(Duration.ofMinutes(5)));
    assertEquals(Duration.ofMinutes(5), ex.getMaxAge().orElseThrow());
  }

  @Test
  @DisplayName("Should ask for step up with max age when auth_time is unknown")
  void shouldAskStepUpWithoutAuthTime() {
    Actor actor = ActorImpl.builder().uid("u").authenticated(true).mfa(true).build();

    assertThrows(StepUpRequiredException.class, () -> actor.requireMfa(Duration.ofMinutes(5)));
  }

  @Test
  @DisplayName("Should keep mfa and auth time through the map form")
  void shouldRoundTripMap() {
    Instant at = Instant.parse("2026-10-27T10:00:00Z");
    Actor actor = ActorImpl.fromMap(
        ActorImpl.toMap(ActorImpl.builder().uid("u").mfa(true).authenticatedAt(at).build()));

    assertTrue(actor.isMfa());
    assertEquals(at, actor.getAuthenticatedAt().orElseThrow());
  }

  @Test
  @DisplayName("Should map to a 401 with the RFC 9470 challenge")
  void shouldMapChallenge() {
    StepUpRequiredExceptionMapper mapper = new StepUpRequiredExceptionMapper("urn:lugh:acr:mfa");

    Response response =
        mapper.toResponse(new StepUpRequiredException("need mfa", Duration.ofMinutes(5)));

    assertEquals(401, response.getStatus());
    assertEquals(
        "Bearer error=\"insufficient_user_authentication\", error_description=\"need mfa\", "
            + "acr_values=\"urn:lugh:acr:mfa\", max_age=300",
        response.getHeaderString(HttpHeaders.WWW_AUTHENTICATE));
    assertEquals(Map.of("reason", "need mfa"), response.getEntity());
  }
}
